PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE admin_users (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	username VARCHAR(100) NOT NULL, 
	password VARCHAR(255) NOT NULL, 
	full_name VARCHAR(100), 
	email VARCHAR(100), 
	is_active BOOLEAN, 
	created_at DATETIME, 
	last_login DATETIME, role TEXT DEFAULT 'super_admin', password_changed_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	UNIQUE (username)
);
CREATE TABLE assignment_submissions (
	id INTEGER NOT NULL, 
	assignment_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	answer_text TEXT, 
	submission_file VARCHAR(500), 
	submitted_at DATETIME NOT NULL, 
	marks_awarded FLOAT, 
	feedback VARCHAR(1000), 
	graded_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(assignment_id) REFERENCES assignments (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE assignments (
	id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	instructions TEXT NOT NULL, 
	due_date DATETIME, 
	marks FLOAT NOT NULL, 
	module_id INTEGER, 
	attachment_path VARCHAR(500), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(module_id) REFERENCES course_modules (id)
);
CREATE TABLE audit_logs (
	id INTEGER NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id INTEGER, 
	action_type VARCHAR(50) NOT NULL, 
	actor_id INTEGER, 
	actor_role VARCHAR(30), 
	before_values TEXT, 
	after_values TEXT, 
	metadata_json TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(actor_id) REFERENCES users (id)
);
CREATE TABLE chatbot_conversations (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	course_id INTEGER, 
	user_message TEXT NOT NULL, 
	bot_response TEXT NOT NULL, 
	domain VARCHAR(100), 
	timestamp DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);

Suggested next questions:
- Why these courses?
- Show my skill gaps
- Give me project ideas',NULL,'2026-03-13 02:53:56.080141');
CREATE TABLE coding_challenges (
	id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT NOT NULL, 
	difficulty VARCHAR(50) NOT NULL, 
	topic VARCHAR(100) NOT NULL, 
	starter_code TEXT, 
	expected_output TEXT, 
	test_cases_json TEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (title)
);
CREATE TABLE coding_submissions (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	challenge_id INTEGER NOT NULL, 
	code_submitted TEXT NOT NULL, 
	execution_output TEXT, 
	passed_tests INTEGER NOT NULL, 
	score FLOAT NOT NULL, 
	submitted_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(challenge_id) REFERENCES coding_challenges (id)
);
CREATE TABLE community_answers (
	id INTEGER NOT NULL, 
	post_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	answer_text TEXT NOT NULL, 
	votes INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(post_id) REFERENCES community_posts (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE community_posts (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	content TEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE contact_message (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	message VARCHAR(1000) NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE contact_messages (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	message VARCHAR(1000) NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE course (
	id INTEGER NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	description VARCHAR(500), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE course_modules (
	id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	order_index INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE courses (
	id INTEGER NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	description VARCHAR(1000), 
	domain_id INTEGER NOT NULL, 
	price FLOAT, 
	instructor VARCHAR(100), 
	image_url VARCHAR(500), 
	demo_video_url VARCHAR(500), 
	created_at DATETIME, status TEXT DEFAULT 'draft', 
	PRIMARY KEY (id), 
	FOREIGN KEY(domain_id) REFERENCES domains (id)
);
CREATE TABLE domains (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description VARCHAR(500), 
	created_at DATETIME, image_url TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE enrollments (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	enrolled_date DATETIME, 
	progress FLOAT, 
	completed BOOLEAN, progress_percentage REAL DEFAULT 0.0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE interview_questions (
	id INTEGER NOT NULL, 
	session_id INTEGER NOT NULL, 
	question_text TEXT NOT NULL, 
	question_type VARCHAR(50) NOT NULL, 
	expected_answer TEXT, 
	difficulty VARCHAR(50) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(session_id) REFERENCES interview_sessions (id)
);
CREATE TABLE interview_responses (
	id INTEGER NOT NULL, 
	session_id INTEGER NOT NULL, 
	question_id INTEGER NOT NULL, 
	user_answer TEXT, 
	ai_feedback TEXT, 
	score FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(session_id) REFERENCES interview_sessions (id), 
	FOREIGN KEY(question_id) REFERENCES interview_questions (id)
);
CREATE TABLE interview_sessions (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	role VARCHAR(100) NOT NULL, 
	difficulty VARCHAR(50) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME, 
	score FLOAT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE learning_streaks (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	last_learning_date DATE, 
	current_streak INTEGER NOT NULL, 
	longest_streak INTEGER NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE lesson_progress (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	lesson_id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	completed BOOLEAN NOT NULL, 
	completed_at DATETIME, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_lesson_progress_user_lesson UNIQUE (user_id, lesson_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(lesson_id) REFERENCES videos (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE project_ideas (
	id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT NOT NULL, 
	domain VARCHAR(100) NOT NULL, 
	difficulty VARCHAR(50) NOT NULL, 
	tech_stack TEXT, 
	architecture TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE project_tasks (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	task_title VARCHAR(200) NOT NULL, 
	task_description TEXT, 
	task_order INTEGER NOT NULL, 
	completed BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES student_projects (id)
);
CREATE TABLE quiz_answers (
	id INTEGER NOT NULL, 
	attempt_id INTEGER NOT NULL, 
	question_id INTEGER NOT NULL, 
	submitted_answer TEXT, 
	is_correct BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(attempt_id) REFERENCES quiz_attempts (id), 
	FOREIGN KEY(question_id) REFERENCES quiz_questions (id)
);
CREATE TABLE quiz_attempts (
	id INTEGER NOT NULL, 
	quiz_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	attempt_number INTEGER NOT NULL, 
	total_questions INTEGER NOT NULL, 
	correct_answers INTEGER NOT NULL, 
	score_percentage FLOAT NOT NULL, 
	passed BOOLEAN NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME, 
	started_at DATETIME NOT NULL, 
	submitted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(quiz_id) REFERENCES quizzes (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE quiz_questions (
	id INTEGER NOT NULL, 
	quiz_id INTEGER NOT NULL, 
	question_text TEXT NOT NULL, 
	question_type VARCHAR(30) NOT NULL, 
	option_a VARCHAR(500), 
	option_b VARCHAR(500), 
	option_c VARCHAR(500), 
	option_d VARCHAR(500), 
	correct_answer VARCHAR(500) NOT NULL, 
	order_index INTEGER NOT NULL, 
	order_number INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(quiz_id) REFERENCES quizzes (id)
);
CREATE TABLE quizzes (
	id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description VARCHAR(1000), 
	question_count_target INTEGER NOT NULL, 
	passing_percentage FLOAT NOT NULL, 
	time_limit_minutes INTEGER NOT NULL, 
	attempts_allowed INTEGER NOT NULL, 
	is_enabled BOOLEAN NOT NULL, 
	module_id INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(module_id) REFERENCES course_modules (id)
);
CREATE TABLE referral_transactions (
	id INTEGER NOT NULL, 
	referrer_id INTEGER NOT NULL, 
	new_user_id INTEGER NOT NULL, 
	reward_amount FLOAT, 
	status VARCHAR(20), 
	date DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(referrer_id) REFERENCES users (id), 
	FOREIGN KEY(new_user_id) REFERENCES users (id)
);
CREATE TABLE skill_progress (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	skill_name VARCHAR(200) NOT NULL, 
	progress_percentage FLOAT NOT NULL, 
	last_updated DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_skill_progress_user_skill UNIQUE (user_id, skill_name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE student_projects (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	progress_percentage FLOAT NOT NULL, 
	started_at DATETIME NOT NULL, 
	completed_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(project_id) REFERENCES project_ideas (id)
);
CREATE TABLE syllabuses (
	id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	topic_title VARCHAR(200) NOT NULL, 
	topic_description VARCHAR(1000), 
	order_number INTEGER NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE user_badges (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	badge_name VARCHAR(100) NOT NULL, 
	awarded_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE user_resumes (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	resume_path VARCHAR(500), 
	skills_json TEXT, 
	projects_json TEXT, 
	education_json TEXT, 
	experience_json TEXT, 
	uploaded_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE user_xp (
	user_id INTEGER NOT NULL, 
	xp_points INTEGER NOT NULL, 
	level INTEGER NOT NULL, 
	PRIMARY KEY (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	password VARCHAR(255) NOT NULL, 
	role VARCHAR(20), 
	referral_code VARCHAR(20) NOT NULL, 
	referred_by VARCHAR(20), 
	wallet_balance FLOAT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (email), 
	UNIQUE (referral_code)
);
CREATE TABLE video (
	id INTEGER NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	video_url VARCHAR(500) NOT NULL, 
	description VARCHAR(500), 
	course_id INTEGER NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES course (id)
);
CREATE TABLE videos (
	id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	video_url VARCHAR(500) NOT NULL, 
	description VARCHAR(500), 
	duration VARCHAR(20), 
	order_number INTEGER, 
	created_at DATETIME, module_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE INDEX ix_lesson_progress_course_id ON lesson_progress (course_id);
CREATE INDEX ix_lesson_progress_user_id ON lesson_progress (user_id);
CREATE INDEX ix_lesson_progress_lesson_id ON lesson_progress (lesson_id);
CREATE UNIQUE INDEX ix_learning_streaks_user_id ON learning_streaks (user_id);
CREATE INDEX ix_course_modules_course_id ON course_modules (course_id);
CREATE INDEX ix_quizzes_course_id ON quizzes (course_id);
CREATE INDEX ix_quizzes_module_id ON quizzes (module_id);
CREATE INDEX ix_assignments_module_id ON assignments (module_id);
CREATE INDEX ix_assignments_course_id ON assignments (course_id);
CREATE INDEX ix_quiz_questions_quiz_id ON quiz_questions (quiz_id);
CREATE INDEX ix_quiz_attempts_quiz_id ON quiz_attempts (quiz_id);
CREATE INDEX ix_quiz_attempts_user_id ON quiz_attempts (user_id);
CREATE INDEX ix_assignment_submissions_assignment_id ON assignment_submissions (assignment_id);
CREATE INDEX ix_assignment_submissions_user_id ON assignment_submissions (user_id);
CREATE INDEX ix_quiz_answers_attempt_id ON quiz_answers (attempt_id);
CREATE INDEX ix_quiz_answers_question_id ON quiz_answers (question_id);
CREATE INDEX ix_skill_progress_user_id ON skill_progress (user_id);
CREATE INDEX ix_skill_progress_skill_name ON skill_progress (skill_name);
CREATE INDEX ix_coding_challenges_topic ON coding_challenges (topic);
CREATE INDEX ix_coding_submissions_user_id ON coding_submissions (user_id);
CREATE INDEX ix_coding_submissions_challenge_id ON coding_submissions (challenge_id);
CREATE INDEX ix_interview_sessions_role ON interview_sessions (role);
CREATE INDEX ix_interview_sessions_user_id ON interview_sessions (user_id);
CREATE INDEX ix_interview_questions_session_id ON interview_questions (session_id);
CREATE INDEX ix_interview_responses_session_id ON interview_responses (session_id);
CREATE INDEX ix_interview_responses_question_id ON interview_responses (question_id);
CREATE INDEX ix_project_ideas_domain ON project_ideas (domain);
CREATE INDEX ix_community_posts_user_id ON community_posts (user_id);
CREATE INDEX ix_user_badges_user_id ON user_badges (user_id);
CREATE INDEX ix_student_projects_project_id ON student_projects (project_id);
CREATE INDEX ix_student_projects_user_id ON student_projects (user_id);
CREATE INDEX ix_community_answers_user_id ON community_answers (user_id);
CREATE INDEX ix_community_answers_post_id ON community_answers (post_id);
CREATE INDEX ix_project_tasks_project_id ON project_tasks (project_id);
CREATE UNIQUE INDEX ix_user_resumes_user_id ON user_resumes (user_id);
COMMIT;
